import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const RevelacaoRapidaZoomLento: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const t = useCurrentFrame();
  const src = String(anim.params?.src ?? "");
  const revealSecondsRaw = Number(anim.params?.revealSeconds);
  const zoomRaw = Number(anim.params?.zoom);
  const revealSeconds = Number.isFinite(revealSecondsRaw) && revealSecondsRaw > 0 ? revealSecondsRaw : 0.4;
  const zoomEnd = Number.isFinite(zoomRaw) && zoomRaw >= 1 ? Math.min(zoomRaw, 1.6) : 1.15;

  const total = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const revealEnd = Math.max(1, Math.min(total - 1, Math.round(revealSeconds * fps)));

  // Fast diagonal wipe along the brand slash (~11deg, rising to the right).
  const progress = interpolate(t, [0, revealEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const slant = (Math.tan((11 * Math.PI) / 180) * frame.height * 100) / Math.max(1, frame.width);
  const edgeTop = progress * (100 + slant);
  const edgeBottom = edgeTop - slant;
  const clipPath = `polygon(0% 0%, ${edgeTop}% 0%, ${edgeBottom}% 100%, 0% 100%)`;

  // Quick settle during the reveal, then a slow push-in until the layer ends.
  const scale =
    t < revealEnd
      ? interpolate(t, [0, revealEnd], [1.12, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.bezier(0.16, 1, 0.3, 1),
        })
      : interpolate(t, [revealEnd, total], [1, zoomEnd], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.inOut(Easing.quad),
        });

  if (!src) {
    const inset = Math.round(Math.min(frame.width, frame.height) * 0.06);
    return (
      <AbsoluteFill style={{ fontFamily: FONTS.body }}>
        <div
          style={{
            position: "absolute",
            left: inset,
            top: inset,
            right: inset,
            bottom: inset,
            clipPath,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            backgroundColor: "rgba(255,255,255,0.06)",
            border: `${Math.max(2, Math.round(frame.width * 0.003))}px dashed ${dark ? COLORS.mutedOnDark : COLORS.mutedOnLight}`,
          }}
        >
          <div
            style={{
              scale: String(scale),
              color: dark ? COLORS.mutedOnDark : COLORS.mutedOnLight,
              fontWeight: FONTS.bodyWeight,
              fontSize: Math.round(Math.min(frame.width, frame.height) * 0.04),
              letterSpacing: "0.14em",
              textTransform: "uppercase",
              textAlign: "center",
              padding: "0 5%",
            }}
          >
            Sem imagem
          </div>
        </div>
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill style={{ overflow: "hidden", clipPath }}>
      <Img
        src={src}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          transformOrigin: "50% 50%",
          scale: String(scale),
        }}
      />
    </AbsoluteFill>
  );
};

export default RevelacaoRapidaZoomLento;

