import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const SLASH_TAN = Math.tan((11 * Math.PI) / 180);

const RevelacaoImagemZoom: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const src = String(anim.params?.src ?? "");
  const zoomParam = Number(anim.params?.zoom);
  const zoomTo = Number.isFinite(zoomParam) && zoomParam >= 1 ? Math.min(zoomParam, 2) : 1.15;
  const revealParam = Number(anim.params?.revealSeconds);
  const revealSec = Number.isFinite(revealParam) && revealParam > 0 ? revealParam : 0.45;

  const total = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const revealFrames = Math.max(1, Math.min(Math.round(revealSec * fps), Math.floor(total * 0.4)));

  // Box: a margin all round so the brand backdrop still frames the photo.
  const margin = Math.round(Math.min(frame.width, frame.height) * (format === "half" ? 0.06 : 0.067));
  const boxW = frame.width - margin * 2;
  const boxH = frame.height - margin * 2;

  // Fast reveal: a diagonal slash (rises to the right) sweeps left -> right.
  const skew = boxH * SLASH_TAN;
  const edge = interpolate(f, [0, revealFrames], [-skew, boxW + skew], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const clip = `polygon(0px 0px, ${edge + skew}px 0px, ${edge}px ${boxH}px, 0px ${boxH}px)`;

  // Slow zoom: starts slightly punched in during the reveal, then creeps in to the end.
  const scale = interpolate(f, [0, revealFrames, total], [1.06, 1, zoomTo], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.sin),
  });

  // Accent bar riding the reveal edge, gone once the image is fully open.
  const barW = Math.max(6, Math.round(boxW * 0.012));
  const barOpacity = interpolate(f, [revealFrames * 0.7, revealFrames], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const barAngle = (Math.atan2(skew, boxH) * 180) / Math.PI;

  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  return (
    <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", fontFamily: FONTS.body }}>
      <div style={{ position: "relative", width: boxW, height: boxH }}>
        <div style={{ position: "absolute", inset: 0, overflow: "hidden", clipPath: clip }}>
          {src ? (
            <Img
              src={src}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                transform: `scale(${scale})`,
                transformOrigin: "50% 50%",
              }}
            />
          ) : (
            <div
              style={{
                width: "100%",
                height: "100%",
                backgroundColor: COLORS.vellum,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transform: `scale(${scale})`,
              }}
            >
              <span
                style={{
                  color: muted,
                  fontWeight: FONTS.bodyWeight,
                  fontSize: Math.round(Math.min(boxW, boxH) * 0.06),
                  textTransform: "uppercase",
                  letterSpacing: "0.14em",
                }}
              >
                Imagem
              </span>
            </div>
          )}
        </div>
        <div
          style={{
            position: "absolute",
            top: -boxH * 0.05,
            left: edge + skew / 2 - barW / 2,
            width: barW,
            height: boxH * 1.1,
            backgroundColor: COLORS.teal,
            opacity: barOpacity,
            transform: `rotate(${barAngle}deg)`,
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default RevelacaoImagemZoom;
